    def exit_alt():
        try:
            sys.stdout.write("\x1b[?25h\x1b[?1049l")
            sys.stdout.flush()
        except:
            pass
    def get_size():
        try:
            import shutil
            sz = shutil.get_terminal_size()
            return sz.columns, sz.lines
        except:
            return 80, 24
    # Key reading
    def read_key():
        # Returns key string: "q", "s", "d", "r", "h", "j", "k", "l", "Tab", "BTab", "Enter", "Escape", "Up", "Down", "Left", "Right", "F1", "C-c", "+", "-", etc., or single char for input dialogs (printable), "Backspace", etc.
        # Read one byte, if \x1b, read more with timeout to distinguish Escape vs sequences
        try:
            ch = os.read(fd, 1)
        except:
            return None
        if not ch:
            return None
        b = ch[0]
        if b == 0x03:  # Ctrl-C
            return "C-c"
        if b == 0x09:  # Tab
            return "Tab"
        if b == 0x0d or b == 0x0a:  # Enter (CR/LF)
            # In raw mode, Enter is \r (0x0d). Good.
            return "Enter"
        if b == 0x1b:  # Escape or sequence
            # Check if more bytes available (with short timeout)
            import select as _sel
            r, _, _ = _sel.select([fd], [], [], 0.05)
            if not r:
                return "Escape"
            # More bytes, read sequence
            try:
                seq = os.read(fd, 16)  # read up to 16 (enough for F1, arrows, etc.)
            except:
                return "Escape"
            s = ch + seq
            # Parse
            # BTab: \x1b[Z
            if s == b"\x1b[Z":
                return "BTab"
            # Arrows: \x1b[A/B/C/D
            if s.startswith(b"\x1b["):
                rest = s[2:]
                if rest.startswith(b"A"):
                    return "Up"
                if rest.startswith(b"B"):
                    return "Down"
                if rest.startswith(b"C"):
                    return "Right"
                if rest.startswith(b"D"):
                    return "Left"
                if rest.startswith(b"11~"):  # F1 (xterm second form)
                    return "F1"
                # Other \x1b[ sequences? Ignore, return Escape? Or unknown? For simplicity, return "Escape" for unknown sequences? Or return raw? For our purposes, unknown sequences (e.g., Home, End, etc.) do nothing (ignore). Return None? Or "Unknown"? Let's return "Unknown" to ignore.
                return "Unknown"
            if s.startswith(b"\x1bO"):
                # F1 is \x1bOP (xterm first form), also \x1bOQ/R/S for F2-4? Only F1 needed.
                if len(s) >= 3 and s[2:3] == b"P":
                    return "F1"
                return "Unknown"
            # Single Escape followed by other chars? Unlikely. Return Escape?
            return "Escape"
        if b == 0x7f or b == 0x08:  # Backspace (DEL or BS)
            return "Backspace"
        # Printable? Return chr
        try:
            c = chr(b)
            return c
        except:
            return None
