    def read_key():
        try:
            ch = os.read(fd, 1)
        except:
            return None
        if not ch:
            return None
        b = ch[0]
        if b == 0x03:
            return "C-c"
        if b == 0x09:
            return "Tab"
        if b == 0x0d or b == 0x0a:
            return "Enter"
        if b == 0x1b:
            import select as _sel
            r, _, _ = _sel.select([fd], [], [], 0.05)
            if not r:
                return "Escape"
            try:
                seq = os.read(fd, 16)
            except:
                return "Escape"
            s = ch + seq
            if s == b"\x1b[Z":
                return "BTab"
            if s.startswith(b"\x1b["):
                rest = s[2:]
                if rest.startswith(b"A"):
                    return "Up"
                if rest.startswith(b"B"):
                    return "Down"
                if rest.startswith(b"C"):
                    return "Right"
                if rest.startswith(b"D"):
                    return "Left"
                if rest.startswith(b"11~"):
                    return "F1"
                return "Unknown"
            if s.startswith(b"\x1bO"):
                if len(s) >= 3 and s[2:3] == b"P":
                    return "F1"
                return "Unknown"
            return "Escape"
        if b == 0x7f or b == 0x08:
            return "Backspace"
        try:
            return chr(b)
        except:
            return None
